// Separate append-only log database: never opens or writes the artwork store.
import {timeLimits,validTimeId,validateEvent,eventBytes,recordingHeader} from './timelapse.js';
const request=r=>new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});
const range=id=>IDBKeyRange.bound([id,0],[id,timeLimits.events]);
export async function openTimelapseStore(){
 const q=indexedDB.open('unruly-timelapse-v1',1);q.onupgradeneeded=()=>{q.result.createObjectStore('meta',{keyPath:'boardId'});q.result.createObjectStore('events',{keyPath:['boardId','index']});q.result.createObjectStore('budget');};q.onblocked=()=>{};const db=await request(q);db.onversionchange=()=>db.close();
 async function read(id){if(!validTimeId(id))throw Error('Invalid recording board');const tx=db.transaction(['meta','events']),done=new Promise((ok,no)=>{tx.oncomplete=ok;tx.onabort=()=>no(tx.error||Error('Recording read aborted'));});const [meta,rows]=await Promise.all([request(tx.objectStore('meta').get(id)),request(tx.objectStore('events').getAll(range(id)))]);await done;if(!meta){if(rows.length)throw Error('Damaged recording index · original data preserved');return{revision:0,log:null};}if(meta.version!==1||!Number.isSafeInteger(meta.revision)||meta.revision<1||meta.count!==rows.length||rows.some((r,i)=>r.index!==i||r.boardId!==id))throw Error('Damaged recording index · original data preserved');const log={version:1,boardId:id,events:rows.map(r=>r.event)};if(meta.count===0){if(rows.length||meta.bytes!==0)throw Error('Damaged empty recording');return{revision:meta.revision,log:null};}if(recordingHeader(log)!==meta.bytes)throw Error('Damaged recording size · original data preserved');return{revision:meta.revision,log};}
 function write(id,expected,events,replace=false){if(!validTimeId(id)||!Number.isSafeInteger(expected)||expected<0)throw Error('Invalid recording identity');events.forEach(validateEvent);const added=events.reduce((sum,e)=>sum+eventBytes(e),0);return new Promise((ok,no)=>{const tx=db.transaction(['meta','events','budget'],'readwrite'),meta=tx.objectStore('meta'),frames=tx.objectStore('events'),budget=tx.objectStore('budget');let problem,result;const abort=e=>{problem=e;try{tx.abort();}catch{no(e);}};tx.oncomplete=()=>ok(result);tx.onabort=()=>no(problem||tx.error||Error('Recording write aborted'));tx.onerror=()=>{};const get=meta.get(id);get.onsuccess=()=>{const old=get.result;if((old?.revision||0)!==expected){abort(Error('Recording conflict · another tab changed it. Pause and reopen Timelapse.'));return;}if(replace&&old?.count){abort(Error('A recording already exists · back it up and discard it before importing'));return;}const used=budget.get('bytes');used.onsuccess=()=>{try{const count=(old?.count||0)+events.length,total=(old?.bytes||0)+added;if(count>timeLimits.events||total>timeLimits.bytes||(used.result||0)+added>timeLimits.totalBytes)throw Error('Recording limit reached · saved history preserved. Back up and discard to start again.');let at=old?.at??0;for(let i=0;i<events.length;i++){const event=events[i];if(event.at<at||!old?.count&&i===0&&(event.at!==0||event.delta.start!==0||event.delta.remove!==0))throw Error('Invalid recording event order');at=event.at;frames.add({boardId:id,index:(old?.count||0)+i,event:structuredClone(event)});}const revision=expected+1;meta.put({version:1,boardId:id,revision,count,bytes:total,at});budget.put((used.result||0)+added,'bytes');result=revision;}catch(e){abort(e);}};};});}
 function discard(id,expected){return new Promise((ok,no)=>{const tx=db.transaction(['meta','events','budget'],'readwrite');let problem;tx.oncomplete=()=>ok();tx.onabort=()=>no(problem||tx.error||Error('Discard aborted'));tx.onerror=()=>{};const m=tx.objectStore('meta'),get=m.get(id);get.onsuccess=()=>{const old=get.result;if((old?.revision||0)!==expected){problem=Error('Recording conflict · reopen before discarding');tx.abort();return;}const b=tx.objectStore('budget'),used=b.get('bytes');used.onsuccess=()=>{b.put(Math.max(0,(used.result||0)-(old?.bytes||0)),'bytes');m.put({version:1,boardId:id,revision:expected+1,count:0,bytes:0,at:0});tx.objectStore('events').delete(range(id));};};});}
 return{read,append:(id,revision,event)=>write(id,revision,[event]),importLog:(log,expected=0)=>{recordingHeader(log);return write(log.boardId,expected,log.events,true);},discard,close:()=>db.close()};
}
